52	export function parseKey(rawKey) {
53	  let key;
54	  try {
55	    key = decodeURIComponent(rawKey);
56	  } catch {
57	    throw new InvalidKeyError('key is not valid percent-encoded UTF-8');
58	  }
59	
60	  if (key === '') {
61	    throw new InvalidKeyError('key is empty');
62	  }
63	  if (!key.isWellFormed()) {
64	    throw new InvalidKeyError('key is not valid Unicode');
65	  }
66	  if (key.includes('\0')) {
67	    throw new InvalidKeyError('key contains a NUL character');
68	  }
69	  if (key.startsWith('/')) {
70	    throw new InvalidKeyError('key must be a relative path');
71	  }
72	  for (const segment of key.split('/')) {
73	    if (segment === '') {
74	      throw new InvalidKeyError('key contains an empty path segment');
75	    }
76	    if (segment === '.' || segment === '..') {
77	      throw new InvalidKeyError(`key contains a "${segment}" path segment`);
78	    }
79	    if (Buffer.byteLength(segment) > MAX_SEGMENT_BYTES) {
80	      throw new InvalidKeyError(`key path segment is longer than ${MAX_SEGMENT_BYTES} bytes`);
81	    }
82	  }
83	  return key;
