243	    const target = this.pathOf(key);
244	    await this.#assertInsideRoot(path.dirname(target));
245	    let fh;
246	    try {
247	      // O_NOFOLLOW: a symlink as the last component is not a blob (list()
248	      // skips it too) and must not lead out of the root.
249	      fh = await fs.open(target, fsConstants.O_RDONLY | fsConstants.O_NOFOLLOW);
250	    } catch (err) {
251	      // Missing, a path component is a blob rather than a directory, or the
252	      // key names a symlink.
253	      if (err.code === 'ENOENT' || err.code === 'ENOTDIR' || err.code === 'ELOOP') return null;
254	      if (KEY_FS_ERRORS.has(err.code)) {
255	        throw new InvalidKeyError(`key cannot be stored as a file: ${err.code}`);
256	      }
257	      throw err;
258	    }
259	    // Size comes from the open handle, so it matches the bytes we will read
260	    // even if the blob is replaced meanwhile.
261	    const stat = await fh.stat().catch(async (err) => {
262	      await fh.close();
263	      throw err;
264	    });
265	    if (!stat.isFile()) {
266	      // A directory holding other blobs is not a blob itself.
267	      await fh.close();
268	      return null;
269	    }
270	    return { fh, size: stat.size };
271	  }
272	
273	  /**
274	   * Deletes the blob stored under `key`, then removes any parent directories
275	   * that are left empty, so the key's path can later be reused as a blob.
276	   *
277	   * @param {string} key  a key accepted by parseKey()
278	   * @returns {Promise<boolean>} false if there was no such blob
279	   * @throws {InvalidKeyError} if the key cannot name a file here
280	   */
281	  async delete(key) {
282	    const target = this.pathOf(key);
283	    await this.#assertInsideRoot(path.dirname(target));
284	    try {
285	      // unlink() would remove a symlink itself rather than its target, but
286	      // a symlink is not a blob either, so leave it alone.
287	      if (!(await fs.lstat(target)).isFile()) return false;
288	      await fs.unlink(target);
289	    } catch (err) {
290	      // Missing, a path component is a blob, or the key names a directory
291	      // of other blobs: in each case there is no blob to delete.
292	      if (err.code === 'ENOENT' || err.code === 'ENOTDIR' || err.code === 'EISDIR') return false;
293	      if (KEY_FS_ERRORS.has(err.code)) {
294	        throw new InvalidKeyError(`key cannot be stored as a file: ${err.code}`);
295	      }
296	      throw err;
297	    }
298	    await this.#pruneEmptyDirs(path.dirname(target));
299	    return true;
300	  }
301	
302	  async #pruneEmptyDirs(dir) {
303	    for (; dir !== this.root && dir.startsWith(this.root + path.sep); dir = path.dirname(dir)) {
304	      try {
305	        await fs.rmdir(dir);
306	      } catch {
307	        // Not empty (the common case), already gone, or not removable: the
308	        // blob itself is deleted either way, so stop here.
309	        return;
310	      }
311	    }
312	  }
313	
314	  /**
315	   * Lists all blobs, sorted by key.
316	   *
317	   * @returns {Promise<Array<{ key: string, size: number, sha256: string, modified_at: string }>>}
318	   */
319	  async list() {
320	    const blobs = [];
321	    await this.#walk(this.root, [], blobs);
322	    return blobs.sort((a, b) => (a.key < b.key ? -1 : a.key > b.key ? 1 : 0));
323	  }
324	
325	  async #walk(dir, prefix, out) {
326	    let entries;
327	    try {
328	      // Names as raw bytes: decoding to strings would silently turn invalid
329	      // UTF-8 into U+FFFD and report a key that GET can never find.
330	      entries = await fs.readdir(dir, { withFileTypes: true, encoding: 'buffer' });
331	    } catch (err) {
332	      // Nothing stored yet, or the directory vanished while we walked.
333	      if (err.code === 'ENOENT') return;
334	      throw err;
335	    }
336	    for (const entry of entries) {
337	      const name = decodeName(entry.name);
338	      // Only a file put on disk by hand can have such a name; no key reaches it.
339	      if (name === null) continue;
340	      const segments = [...prefix, name];
341	      const full = path.join(dir, name);
342	      if (entry.isDirectory()) {
343	        await this.#walk(full, segments, out);
344	      } else if (entry.isFile()) {
345	        const meta = await describe(full);
346	        if (meta) out.push({ key: segments.join('/'), ...meta });
347	      }
348	    }
349	  }
350	}
