352	// How many times put() recreates parent directories that a concurrent
353	// delete() pruned between our mkdir and rename.
354	const RENAME_ATTEMPTS = 5;
355	
356	// Moves `tmp` to `target`, creating target's parent directories.
357	// `checkDir` vets the parent directory before mkdir, so nothing gets created
358	// through a symlink leading elsewhere, and again right before the rename.
359	async function renameInto(tmp, target, checkDir) {
360	  const dir = path.dirname(target);
361	  for (let attempt = 1; ; attempt++) {
362	    await checkDir(dir);
363	    try {
364	      await fs.mkdir(dir, { recursive: true });
365	      await checkDir(dir);
366	      await fs.rename(tmp, target);
367	      return;
368	    } catch (err) {
369	      // `tmp` is ours, so ENOENT means a parent directory vanished while
370	      // mkdir was building the chain or before the rename.
371	      if (err.code !== 'ENOENT' || attempt >= RENAME_ATTEMPTS) throw err;
372	    }
373	  }
374	}
375	
376	// ignoreBOM keeps a leading U+FEFF, which is part of the name.
377	const utf8 = new TextDecoder('utf-8', { fatal: true, ignoreBOM: true });
378	
379	// A file name read as bytes, decoded as a key segment; null if it is not
380	// valid UTF-8.
