382	  try {
383	    return utf8.decode(bytes);
384	  } catch {
385	    return null;
386	  }
387	}
388	
389	// Size, hash and mtime of one file, all taken from the same open handle so
390	// they stay consistent even if the blob is replaced concurrently. Returns
391	// null if the file disappeared in the meantime.
392	async function describe(file) {
393	  let fh;
394	  try {
395	    fh = await fs.open(file, 'r');
396	  } catch (err) {
397	    if (err.code === 'ENOENT') return null;
398	    throw err;
399	  }
400	  try {
401	    const stat = await fh.stat();
402	    const hash = createHash('sha256');
403	    for await (const chunk of fh.createReadStream({ autoClose: false })) {
