1	#!/usr/bin/env node
2	// Entry point: syncbox-server --data-dir <path> [--port <n>]
3	// Runs in the foreground until SIGINT/SIGTERM.
4	
5	import fs from 'node:fs/promises';
6	import path from 'node:path';
7	
8	import { BlobStore } from './blobs.js';
9	import { ConfigError, USAGE, parseConfig } from './config.js';
10	import { createServer } from './server.js';
11	
12	const EXIT_USAGE = 2;
13	
14	async function main() {
15	  let config;
16	  try {
17	    config = parseConfig(process.argv.slice(2), process.env);
18	  } catch (err) {
19	    if (err instanceof ConfigError) {
20	      console.error(`syncbox-server: ${err.message}\n\n${USAGE}`);
21	      process.exit(EXIT_USAGE);
22	    }
23	    throw err;
24	  }
25	
26	  if (config.help) {
27	    console.log(USAGE);
28	    return;
29	  }
30	
31	  const dataDir = path.resolve(config.dataDir);
32	  const store = new BlobStore(dataDir);
33	  try {
34	    await prepareDataDir(dataDir);
35	    await store.prepare();
36	  } catch (err) {
37	    console.error(`syncbox-server: data directory ${dataDir} is not usable: ${err.message}`);
38	    process.exit(1);
39	  }
