56	    // file that shrinks while being read would leave the server waiting for
57	    // bytes that never come.
58	    const res = await this.#request('PUT', `${this.base}/blobs/${encodeKey(key)}`, {
59	      headers: { 'Content-Type': 'application/octet-stream' },
60	      body: fs.createReadStream(file),
61	    });
