68	  /**
69	   * @param {string} method
70	   * @param {string} url
71	   * @param {{ headers?: Record<string, string>, body?: import('node:stream').Readable }} [options]
72	   * @returns {Promise<{ status: number, statusText: string, body: Buffer }>}
73	   */
74	  #request(method, url, { headers = {}, body } = {}) {
75	    return new Promise((resolve, reject) => {
76	      const transport = url.startsWith('https:') ? https : http;
77	      const req = transport.request(url, { method, headers }, (res) => {
78	        const chunks = [];
79	        res.on('data', (chunk) => chunks.push(chunk));
80	        res.on('end', () => resolve({ status: res.statusCode, statusText: res.statusMessage, body: Buffer.concat(chunks) }));
81	        res.on('error', (err) => reject(this.#networkError(err)));
82	      });
83	      req.on('error', (err) => reject(this.#networkError(err)));
84	      if (!body) {
85	        req.end();
86	        return;
87	      }
88	      body.on('error', (err) => {
89	        // A local read error, not a network one: report it as it is.
90	        reject(err);
91	        req.destroy();
92	      });
93	      body.pipe(req);
94	    });
95	  }
96	
97	  #networkError(err) {
98	    // With several addresses to try (::1 and 127.0.0.1 for localhost) the
99	    // error is an AggregateError whose own message may be empty.
100	    const detail = err.errors?.length ? err.errors.map((e) => e.message).join('; ') : err.message || err.code;
101	    return new RequestError(`cannot reach server ${this.server.href}: ${detail}`);
102	  }
103	}
104	
105	/**
106	 * Percent-encodes a key for use in a URL path. Each segment is encoded on its
107	 * own so the "/" separators stay as they are.
108	 *
109	 * @param {string} key
110	 * @returns {string}
111	 */
112	export function encodeKey(key) {
113	  return key.split('/').map(encodeURIComponent).join('/');
114	}
115	
116	function describeFailure(res) {
117	  const text = res.body.toString('utf8');
118	  let detail;
119	  try {
120	    detail = JSON.parse(text)?.error ?? text;
121	  } catch {
122	    detail = text;
123	  }
124	  detail = String(detail).trim().slice(0, 200);
125	  return `server answered ${res.status} ${res.statusText}${detail ? ` (${detail})` : ''}`;
126	}

